use data::*;

macro_rules! implies {
  ($lhs: expr, $rhs: expr) => {
    !$lhs || $rhs
  };
}

macro_rules! impliesL {
  ($lhs: expr, $rhs: expr) => {
    !$lhs | $rhs
  };
}

/** Compute Entrypoint Contract
  *
  * guarantee orOutput
  * @param api_channel1 incoming data port
  * @param api_channel2 incoming data port
  * @param api_actuate outgoing data port
  */
pub fn compute_spec_orOutput_guarantee(
  api_channel1: bool,
  api_channel2: bool,
  api_actuate: bool) -> bool
{
  api_actuate == api_channel1 | api_channel2
}

/** CEP-T-Guar: Top-level guarantee contracts for orLogic's compute entrypoint
  *
  * @param api_channel1 incoming data port
  * @param api_channel2 incoming data port
  * @param api_actuate outgoing data port
  */
pub fn compute_CEP_T_Guar(
  api_channel1: bool,
  api_channel2: bool,
  api_actuate: bool) -> bool
{
  let r0: bool = compute_spec_orOutput_guarantee(api_channel1, api_channel2, api_actuate);

  return r0;
}

/** CEP-Post: Compute Entrypoint Post-Condition for orLogic
  *
  * @param api_channel1 incoming data port
  * @param api_channel2 incoming data port
  * @param api_actuate outgoing data port
  */
pub fn compute_CEP_Post(
  api_channel1: bool,
  api_channel2: bool,
  api_actuate: bool) -> bool
{
  // CEP-Guar: guarantee clauses of orLogic's compute entrypoint
  let r0: bool = compute_CEP_T_Guar(api_channel1, api_channel2, api_actuate);

  return r0;
}
